/*!50001 CREATE VIEW `view_member_dashboard` AS SELECT
 1 AS `memberID`,
  1 AS `firstname`,
  1 AS `lastname`,
  1 AS `relationship`,
  1 AS `headID`,
  1 AS `head_firstname`,
  1 AS `head_lastname`,
  1 AS `sector_array_string`,
  1 AS `dt_deleted` */;
